      if (!t) { bad.push(`${id}: no label`); continue; }
      if (t.length * CW > r.w - 2 * SPEC.node.inset + 0.5) bad.push(`${id}: label "${t}" is ${t.length * CW} px in a ${r.w} px box`);
      if (t !== d.nodes[id].label && !t.includes('…')) bad.push(`${id}: cut without an ellipsis`);
      if (unesc(title || '') !== d.nodes[id].path) bad.push(`${id}: tooltip "${title}" is not the full path`);
      if (labels.has(t)) bad.push(`${id} and ${labels.get(t)} both read "${t}"`); labels.set(t, id);
