      const t = (/<text [^>]*>([^<]*)<\/text>/.exec(hg) || [])[1];
      if (!t) { sbad.push(`${sec}: no header`); continue; }
      if (t !== el.label && !(/<title>([^<]*)<\/title>/.exec(hg) || [])[1]?.startsWith(el.label)) sbad.push(`${sec}: header cut to "${t}" with no tooltip naming "${el.label}"`);
